.version 8.0
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<40>;
    .reg .f32 %f<24>;
    .shared .align 4 .b8 As[2048];
    .shared .align 4 .b8 Bs[2048];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [N];
    cvta.to.global.u64 %rd4, %rd1;
    cvta.to.global.u64 %rd5, %rd2;
    cvta.to.global.u64 %rd6, %rd3;
    mov.u32 %r2, %tid.x;            // tx (0..15)
    mov.u32 %r3, %tid.y;            // ty (0..15)
    mov.u32 %r4, %ctaid.x;          // bx
    mov.u32 %r5, %ctaid.y;          // by
    mul.lo.s32 %r6, %r5, 32;        // rowBase
    mul.lo.s32 %r7, %r4, 32;        // colBase
    add.s32 %r8, %r6, %r3;          // row0
    add.s32 %r9, %r8, 16;           // row1
    add.s32 %r10, %r7, %r2;         // col0
    add.s32 %r11, %r10, 16;         // col1
    mov.f32 %f1, 0f00000000;        // acc00
    mov.f32 %f2, 0f00000000;        // acc01
    mov.f32 %f3, 0f00000000;        // acc10
    mov.f32 %f4, 0f00000000;        // acc11
    shr.u32 %r12, %r1, 4;           // numTiles = N/16
    mov.u32 %r13, 0;                // t
LOOP_START:
    setp.ge.u32 %p1, %r13, %r12;
    @%p1 bra LOOP_END;
    mad.lo.s32 %r14, %r13, 16, %r2; // aCol = t*16+tx
    mad.lo.s32 %r15, %r8, %r1, %r14;
    mul.wide.s32 %rd10, %r15, 4;
    add.s64 %rd11, %rd4, %rd10;
    ld.global.f32 %f5, [%rd11];
    mad.lo.s32 %r16, %r3, 16, %r2;  // As[ty][tx] idx
    mul.lo.s32 %r17, %r16, 4;
    mov.u32 %r18, As;
    add.s32 %r19, %r18, %r17;
    st.shared.f32 [%r19], %f5;
    mad.lo.s32 %r20, %r9, %r1, %r14;
    mul.wide.s32 %rd12, %r20, 4;
    add.s64 %rd13, %rd4, %rd12;
    ld.global.f32 %f6, [%rd13];
    add.s32 %r21, %r16, 256;        // As[ty+16][tx] idx
    mul.lo.s32 %r22, %r21, 4;
    add.s32 %r23, %r18, %r22;
    st.shared.f32 [%r23], %f6;
    mad.lo.s32 %r24, %r13, 16, %r3; // bRow = t*16+ty
    mad.lo.s32 %r25, %r24, %r1, %r10;
    mul.wide.s32 %rd14, %r25, 4;
    add.s64 %rd15, %rd5, %rd14;
    ld.global.f32 %f7, [%rd15];
    mad.lo.s32 %r26, %r3, 32, %r2;  // Bs[ty][tx] idx
    mul.lo.s32 %r27, %r26, 4;
    mov.u32 %r28, Bs;
    add.s32 %r29, %r28, %r27;
    st.shared.f32 [%r29], %f7;
    mad.lo.s32 %r30, %r24, %r1, %r11;
    mul.wide.s32 %rd16, %r30, 4;
    add.s64 %rd17, %rd5, %rd16;
    ld.global.f32 %f8, [%rd17];
    add.s32 %r31, %r26, 16;         // Bs[ty][tx+16] idx
    mul.lo.s32 %r32, %r31, 4;
    add.s32 %r33, %r28, %r32;
    st.shared.f32 [%r33], %f8;
    bar.sync 0;
    mov.u32 %r34, 0;                // k
INNER_LOOP:
    setp.ge.u32 %p2, %r34, 16;
    @%p2 bra INNER_END;
    mad.lo.s32 %r35, %r3, 16, %r34; // As[ty][k] idx
    mul.lo.s32 %r36, %r35, 4;
    add.s32 %r37, %r18, %r36;
    ld.shared.f32 %f9, [%r37];
    add.s32 %r38, %r35, 256;        // As[ty+16][k] idx
    mul.lo.s32 %r39, %r38, 4;
    add.s32 %r40, %r18, %r39;
    ld.shared.f32 %f10, [%r40];
    mad.lo.s32 %r41, %r34, 32, %r2; // Bs[k][tx] idx
    mul.lo.s32 %r42, %r41, 4;
    add.s32 %r43, %r28, %r42;
    ld.shared.f32 %f11, [%r43];
    add.s32 %r44, %r41, 16;         // Bs[k][tx+16] idx
    mul.lo.s32 %r45, %r44, 4;
    add.s32 %r46, %r28, %r45;
    ld.shared.f32 %f12, [%r46];
    fma.rn.f32 %f1, %f9, %f11, %f1;  // acc00 += a0*b0
    fma.rn.f32 %f2, %f9, %f12, %f2;  // acc01 += a0*b1
    fma.rn.f32 %f3, %f10, %f11, %f3; // acc10 += a1*b0
    fma.rn.f32 %f4, %f10, %f12, %f4; // acc11 += a1*b1
    add.u32 %r34, %r34, 1;
    bra INNER_LOOP;
INNER_END:
    bar.sync 0;
    add.u32 %r13, %r13, 1;
    bra LOOP_START;
LOOP_END:
    mad.lo.s32 %r50, %r8, %r1, %r10;
    mul.wide.s32 %rd20, %r50, 4;
    add.s64 %rd21, %rd6, %rd20;
    st.global.f32 [%rd21], %f1;
    mad.lo.s32 %r51, %r8, %r1, %r11;
    mul.wide.s32 %rd22, %r51, 4;
    add.s64 %rd23, %rd6, %rd22;
    st.global.f32 [%rd23], %f2;
    mad.lo.s32 %r52, %r9, %r1, %r10;
    mul.wide.s32 %rd24, %r52, 4;
    add.s64 %rd25, %rd6, %rd24;
    st.global.f32 [%rd25], %f3;
    mad.lo.s32 %r53, %r9, %r1, %r11;
    mul.wide.s32 %rd26, %r53, 4;
    add.s64 %rd27, %rd6, %rd26;
    st.global.f32 [%rd27], %f4;
    ret;
